import collections

def transform(grid):
    # Identify the background color as the most frequent one
    counts = collections.Counter()
    for row in grid:
        for cell in row:
            counts[cell] += 1

    bg_color = counts.most_common(1)[0][0]

    h = len(grid)
    w = len(grid[0])

    # Initialize output grid filled with background color
    output = [[bg_color] * w for _ in range(h)]

    # Iterate through input grid and shift non-background pixels right
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg_color:
                if c + 1 < w:
                    output[r][c+1] = grid[r][c]

    return output
